/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `trg_tb_products_after_delete` AFTER DELETE ON `tb_products` FOR EACH ROW BEGIN
    INSERT INTO `tb_logs` (
        `table_name`,
        `table_operation`,
        `db_user`,
        `table_description`,
        `operation_date`,
        `operation_status`
    )
    VALUES (
        'tb_products',
        'Delete',
        USER(),
        CONCAT(
            'Producto eliminado. ID=', OLD.ID,
            ', SKU=', OLD.SKU,
            ', nombre=', OLD.name,
            ', descripci¢n=', COALESCE(OLD.description, 'NULL'),
            ', precio=', OLD.current_price,
            ', stock=', OLD.current_stock,
            ', status=', COALESCE(OLD.status, b'0')
        ),
        CURRENT_TIMESTAMP,
        b'1'
    );
END */;;
